// The city's texts (city.js) in French, as the sentences take them: server after "Le serveur" ("Le serveur de la
// ville de Brno ne répond pas"), dataName as a subject ("… ne répond pas pour l'instant"), dataShort after "les
// données" ("d'après les données de la ville de Brno et d'OSM"), techMap as the subject of "… en cours de chargement".
const own = (name, of, map, data, parking, credit) => ({
  server: of, dataName: map, dataShort: `${data} et d'OSM`, techMap: map,
  parkingSource: parking, rulesHead: `Largeurs selon le manuel pragois de l'IPR (C.2), à titre indicatif pour ${name} :`, credit,
});
